const body = $('Primeiro Tratamento de Informações').item.json;
const data = body.data || {};

const textFromMessage = (
  (data.message && data.message.conversation) ||
  (data.message && data.message.text) ||
  (data.message && data.message.extendedTextMessage && data.message.extendedTextMessage.text) ||
  ''
).trim();

const textFromImage = ($json && $json.mensagem) || '';

const text = textFromImage || textFromMessage;

const remoteJid = ($json && $json.remoteJid) || '';
const keyRemoteJid = (data.key && data.key.remoteJid) || '';
const groupJid = remoteJid || keyRemoteJid || '';
const groupKey = groupJid.split('@')[0];

const sender =
  (data.key && data.key.participantAlt) ||
  (data.key && data.key.participant) ||
  body.sender ||
  '';

const senderPhone = sender.split('@')[0];
const messageId = (data.key && data.key.id) || '';

const ts = data.messageTimestamp;
const timestamp = typeof ts === 'number'
  ? (ts < 2e12 ? ts * 1000 : ts)
  : (ts ? Number(ts) * 1000 : Date.now());

const pushName = data.pushName || 'Desconhecido';

return [{
  json: {
    text,
    groupJid,
    groupKey,
    sender,
    senderPhone,
    senderName: pushName,
    messageId,
    timestamp,
    raw: body,
  }
}];

function tryParse(value) {
  if (!value || value === "null") return null;
  try { return JSON.parse(value); } catch { return value; }
}
function extractJson(raw) {
  if (!raw) return { descricao: null, resolucao: null };
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) return { descricao: null, resolucao: null };
  try { return JSON.parse(match[0]); } catch { return { descricao: null, resolucao: null }; }
}

const aiItem     = items.find(i => "output" in i.json);
const ticketItem = items.find(i => "groupJid" in i.json || "arandaTicketId" in i.json);
const msgItems   = items.filter(i => "whatsapp_id" in i.json || "message_body" in i.json);

const aiOutput   = aiItem?.json?.output ?? null;
const resumo     = extractJson(aiOutput);

const ticket     = ticketItem?.json ?? {};

const mensagens  = msgItems.map(i => ({
  senderName:        i.json.sender_name   ?? i.json.senderName   ?? null,
  senderPhone:       i.json.sender_phone  ?? i.json.senderPhone  ?? null,
  messageBody:       i.json.message_body  ?? i.json.messageBody  ?? null,
  messageType:       i.json.message_type  ?? i.json.messageType  ?? null,
  mediaUrl:          i.json.media_url     ?? i.json.mediaUrl     ?? null,
  timestampWhatsapp: i.json.timestamp_whatsapp ?? i.json.timestampWhatsapp ?? null,
}));

const payload = {
  id:             ticket.id             ?? null,
  arandaTicketId: ticket.arandaTicketId ?? null,
  "case-id":      (ticket["case-id"] ?? ticket.caseId ?? "").replace(/\D/g, ""),
  groupJid:       ticket.groupJid       ?? null,
  status:         ticket.status?.toUpperCase() ?? null,
  openedBy:       ticket.openedBy       ?? null,
  openedByName:   ticket.openedByName   ?? null,
  openedAt:       ticket.openedAt       ?? null,
  closedBy:       ticket.closedBy       ?? null,
  closedAt:       ticket.closedAt       ?? null,
  descricao:      resumo.descricao      ?? null,  // ← só o que aconteceu
  resolucao:      resumo.resolucao      ?? null,  // ← como foi resolvido
  mensagens,
  log: tryParse(ticket.log) ?? [],
};

return [{ json: payload }];

// Pega o arandaTicketId do chamado ativo
const arandaTicketId = $json.arandaTicketId || '';

// Extrai só o número (ex: RF-TI-53751 → 53751)
const fileItemId = arandaTicketId.replace(/\D/g, '');

const senderName = $json.senderName || 'Usuário WhatsApp';
const groupJid   = $json.groupJid  || '';

if (!fileItemId) {
  throw new Error('Nenhum chamado ativo encontrado para anexar a imagem. arandaTicketId: ' + arandaTicketId);
}

return [{
  json: {
    fileItemId,
    fileItemType: '1',
    concept:      '0',
    uploadType:   '0',
    description:  'Imagem enviada via WhatsApp por ' + senderName,
    isPublic:     'true',
    groupJid,
    senderName,
    arandaTicketId,
  }
}];

const MESSAGES = {
