// n8n Code node (JavaScript)
// Gera payload padrão para ARANDA ASMS v9 - POST /api/v9/item/

// ====== FIXOS (ajuste aqui) ======
const FIXED = {
  authorId: 1,
  modelId: 18,
  projectId: 2,
  serviceId: 78,
  categoryId: 322,
  stateId: 190,
  consoleType: "specialist",
  customerId: 64,
  applicantId: 64,
  urgencyId: 5,
  itemType: 4,
  groupId: 2730,
  responsibleId: 623,
  companyId: null,
  listAdditionalField: [],
  tempItemId: -3,
  validate: true,
  registryTypeId: 3149,
};

const items = $input.all();

function safeStr(v) {
  return (v ?? "").toString().trim();
}

function toNumber(v, fallback = null) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

const out = [];

for (const item of items) {
  const j = item.json || {};

  const text =
    safeStr(j.messageText) ||
    safeStr(j.text) ||
    safeStr(j.message?.text) ||
    safeStr(j.body?.text) ||
    safeStr(j.raw?.body?.data?.message?.conversation);

  const senderName =
    safeStr(j.senderName) ||
    safeStr(j.pushName) ||
    safeStr(j.raw?.body?.data?.pushName) ||
    "Usuário WhatsApp";

  const senderPhone =
    safeStr(j.senderPhone) ||
    safeStr(j.sender) ||
    safeStr(j.raw?.body?.data?.key?.participantAlt)?.split("@")[0] ||
    safeStr(j.raw?.body?.data?.key?.remoteJid)?.split("@")[0] ||
    "";

  const messageId =
    safeStr(j.messageId) ||
    safeStr(j.raw?.body?.data?.key?.id) ||
    "";

  const groupJid =
    safeStr(j.groupJid) ||
    safeStr(j.raw?.body?.data?.key?.remoteJid) ||
    "";

  const isGroup = groupJid.endsWith("@g.us");

  const timestamp = j.timestamp || j.raw?.body?.data?.messageTimestamp || null;

  const when = timestamp
    ? new Date(toNumber(timestamp, Date.now())).toLocaleString("pt-BR")
    : new Date().toLocaleString("pt-BR");

  const subject = `Chamado WhatsApp - ${senderName}`;

  const description =
    `Chamado aberto automaticamente via WhatsApp.<br>` +
    `Solicitante: ${senderName}${senderPhone ? ` (${senderPhone})` : ""}<br>` +
    `${isGroup ? `Grupo: ${groupJid}<br>` : ""}` +
    `${messageId ? `Mensagem ID: ${messageId}<br>` : ""}` +
    `Data: ${when}<br>` +
    (text ? `Conteúdo: ${text}` : "");

  const arandaPayload = {
    authorId:            FIXED.authorId,
    modelId:             FIXED.modelId,
    projectId:           FIXED.projectId,
    serviceId:           FIXED.serviceId,
    categoryId:          FIXED.categoryId,
    stateId:             FIXED.stateId,
    subject,
    companyId:           FIXED.companyId,
    consoleType:         FIXED.consoleType,
    customerId:          FIXED.customerId,
    urgencyId:           FIXED.urgencyId,
    description,
    itemType:            FIXED.itemType,
    groupId:             FIXED.groupId,
    responsibleId:       FIXED.responsibleId,
    applicantId:         FIXED.applicantId,
    registryTypeId:      FIXED.registryTypeId, 
    listAdditionalField: FIXED.listAdditionalField,
    tempItemId:          FIXED.tempItemId,
    validate:            FIXED.validate,
  };

  out.push({
    json: {
      arandaPayload,
      senderName,
      senderPhone,
      messageId,
      groupJid,
      text,
      timestamp,
    }
  });
}

if (out.length === 0) {
  return [{
    json: {
      skipped: true,
      reason: "Nenhum item de entrada válido",
      inputCount: items.length,
    }
  }];
}

return out;

function tryParse(value) {
  if (!value || value === "null") return null;
  try { return JSON.parse(value); } catch { return value; }
}

// Separa os itens pelo shape
const whatsappItem = items.find(i => "arandaTicketId" in i.json && "groupJid" in i.json);
const arandaItem   = items.find(i => "idByProject" in i.json);

const wa  = whatsappItem?.json ?? {};
const ara = arandaItem?.json   ?? {};

// Monta o commentary com os dados da IA
const linhas = [
  wa.descricao ? `Descrição: ${wa.descricao}` : null,
  wa.resolucao ? `Resolução: ${wa.resolucao}` : "Resolução: Chamado encerrado automaticamente via WhatsApp.",
  wa.openedByName ? `Solicitante: ${wa.openedByName} (${wa.openedBy})` : null,
  wa.openedAt     ? `Aberto em: ${wa.openedAt}` : null,
].filter(Boolean).join("\n");

// Payload exatamente no formato da API Aranda
return [{
  json: {
    id:                  Number((wa["case-id"] ?? ara.id ?? "").toString().replace(/\D/g, "")),
    itemType:            ara.itemType    ?? 4,
    itemVersion:         ara.itemVersion ?? 1,
    modelId:             ara.modelId     ?? 18,
    stateId:             214,
