                   /Suporte TI - Imbera Brasil/i.test(normalized.groupJid)    ||
                   /Suporte TI - Imbera Brasil/i.test(raw.groupName || "")    ||
                   /Suporte TI - Imbera Brasil/i.test(messageText);

  let status;
  if (isBotImb) {
    status = "BotImb";
  } else if (isClose) {
    status = "Ending";
  } else if (isCreate) {
    status = "Create";
  } else {
    const supabaseStatus = raw.status || null;
    if (!supabaseStatus || supabaseStatus === "") {
      status = "HasNoTicketActive";
    } else if (supabaseStatus.toUpperCase() === "COLLECTING") {
      status = "Collecting";
    } else {
      status = "Ignore";
    }
  }

  // ✅ Nova chave: lang detectada pelo groupJid
  const lang = getGroupLang(normalized.groupJid);

  results.push({
    json: {
      ...normalized,
      hasTicketActive,
      status,
      lang, // "pt" | "es" | "en"
    }
  });
}

return results;

