function buildTranscriptionMessage(lang, transcribedText) {
  const m = MESSAGES[lang] || MESSAGES["pt"];
  return (
    m.transcription_title + "\n\n" +
    m.transcription_label + "\n" +
    "> " + transcribedText + "\n\n" +
    m.signature
  );
}

